mapper.select:
/* ProgramMapper.selectProgramList 조회 조건에 맞는 프로그램 목록을 정렬순번 순으로 조회 */ SELECT PRGM_ID, COALESCE(PRGM_NM, '') AS PRGM_NM, COALESCE(LNK_URL, '') AS LNK_URL, COALESCE(PRGM_CRS_CD, '') AS PRGM_CRS_CD, USE_YN, COALESCE(ST_DT, '') AS ST_DT, COALESCE(END_DT, '') AS END_DT, COALESCE(RMK, '') AS RMK FROM TB_PRGM_M
AND PRGM_CRS_CD = #{prgmCrsCd}
AND UPPER(PRGM_ID) LIKE '%' || UPPER(TRIM(#{prgmId})) || '%'
AND UPPER(PRGM_NM) LIKE '%' || UPPER(TRIM(#{prgmNm})) || '%'
AND USE_YN = #{useYn}
ORDER BY ALIN_SEQ NULLS LAST, PRGM_ID

mapper.insert:
/* ProgramMapper.insertProgram 프로그램을 등록 */
INSERT INTO TB_PRGM_M (
    PRGM_ID, PRGM_NM, LNK_URL, PRGM_CRS_CD, USE_YN, ST_DT, END_DT, RMK,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{item.prgmId}, #{item.prgmNm}, NULLIF(#{item.lnkUrl}, ''), NULLIF(#{item.prgmCrsCd}, ''),
    #{item.useYn}, NULLIF(#{item.stDt}, ''), NULLIF(#{item.endDt}, ''), NULLIF(#{item.rmk}, ''),
    #{usrId}, CURRENT_TIMESTAMP, #{usrId}, CURRENT_TIMESTAMP
)

mapper.delete:
/* ProgramMapper.deleteProgram 프로그램을 삭제 */
DELETE FROM TB_PRGM_M
 WHERE PRGM_ID = #{prgmId}

mapper.insert:
/* ProgramMapper.insertProgramComponent 프로그램 컴포넌트를 등록 */
INSERT INTO TB_PRGM_CMPN_M (
    PRGM_ID, CMPN_ID, CMPN_NM, ALIN_SEQ, USE_YN,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{item.prgmId}, #{item.cmpnId}, #{item.cmpnNm}, #{item.alinSeq}, #{item.useYn},
    #{usrId}, CURRENT_TIMESTAMP, #{usrId}, CURRENT_TIMESTAMP
)

mapper.update:
/* ProgramMapper.updateProgramComponent 프로그램 컴포넌트를 수정 */
UPDATE TB_PRGM_CMPN_M
   SET CMPN_NM      = #{item.cmpnNm},
       ALIN_SEQ     = #{item.alinSeq},
       USE_YN       = #{item.useYn},
       FINA_REGR_ID = #{usrId},
       FINA_REG_DT  = CURRENT_TIMESTAMP
 WHERE PRGM_ID = #{item.prgmId}
   AND CMPN_ID = #{item.cmpnId}

mapper.delete:
/* ProgramMapper.deleteProgramComponent 프로그램 컴포넌트를 삭제 */
DELETE FROM TB_PRGM_CMPN_M
 WHERE PRGM_ID = #{prgmId}
   AND CMPN_ID = #{cmpnId}

/* ProgramMapper.deleteProgramComponentList 프로그램의 컴포넌트를 모두 삭제 (프로그램 삭제 시) */
DELETE FROM TB_PRGM_CMPN_M
 WHERE PRGM_ID = #{prgmId}

/* ProgramMapper.deleteProgramAuthGroupComponentList 프로그램 컴포넌트의 권한그룹 컴포넌트 권한을 삭제 (프로그램·컴포넌트 삭제 시) */
DELETE FROM TB_AUTH_GRP_CMPN_R
 WHERE PRGM_ID = #{prgmId}

   AND CMPN_ID = #{cmpnId}

/* ProgramMapper.deleteProgramUserComponentList 프로그램 컴포넌트의 사용자 컴포넌트 권한을 삭제 (프로그램·컴포넌트 삭제 시) */
DELETE FROM TB_USR_CMPN_R
 WHERE PRGM_ID = #{prgmId}

   AND CMPN_ID = #{cmpnId}
